import { useState } from "react";
import axios from "axios";

export default function Cadastrar() {
  const [form, setForm] = useState({
    nome: "",
    idade: "",
    rua: "",
    bairro: "",
    estado: "",
    biografia: "",
    imagem: null,
  });

  function handleChange(e) {
    const { name, value, files } = e.target;
    if (name === "imagem") {
      setForm({ ...form, imagem: files[0] });
    } else {
      setForm({ ...form, [name]: value });
    }
  }

  async function handleSubmit(e) {
    e.preventDefault();
    const data = new FormData();
    Object.entries(form).forEach(([key, value]) => {
      data.append(key, value);
    });

    try {
      await axios.post("http://localhost:3001/usuario", data);
      alert("Usuário cadastrado com sucesso!");
    } catch (error) {
      console.error("Erro ao cadastrar:", error);
      alert("Erro ao cadastrar usuário");
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <input name="nome" placeholder="Nome" onChange={handleChange} />
      <input name="idade" placeholder="Idade" onChange={handleChange} />
      <input name="rua" placeholder="Rua" onChange={handleChange} />
      <input name="bairro" placeholder="Bairro" onChange={handleChange} />
      <input name="estado" placeholder="Estado" onChange={handleChange} />
      <textarea name="biografia" placeholder="Biografia" onChange={handleChange} />
      <input type="file" name="imagem" onChange={handleChange} />
      <button type="submit">Cadastrar</button>
    </form>
  );
}
